def secret(id,kind,rect,lines,why):return dict(id=id,kind=kind,rect=rect,lines=lines,why=why)
def note(rect,lines):return dict(id='public_note',rect=rect,lines=lines,style='note',hint='Это обычная идея для рисунка. Её можно оставить видимой.')
def keep(rect,caption,note_rect,note_lines):return [dict(id='hero',rect=rect,hint='Главный предмет нужен зрителю. Убери с него наклейку.'),dict(id='caption',rect=[.06,.93,.88,.045],lines=[caption],hint='Подпись помогает понять кадр. Оставь её видимой.'),note(note_rect,note_lines)]
def level(id,title,brief,bg,secrets,keep,mode='practice',success='Кадр готов. Носок на посту.'):
 return dict(id=id,title=title,brief=brief,background='./assets/scenes/'+bg+'.svg',mode=mode,maxStickers=4,secrets=secrets,keepZones=keep,helpText='Прочитай записки. Код, пароль и домашний адрес лучше оставить за кадром.',successText=success,posterCaption='Секреты остались за кадром')
address=lambda rect: secret('home_address','address',rect,['Адрес дома','Планета Пример','Дом 0'],'Домашний адрес не стоит показывать всем. Закрой записку целиком.')
code=lambda rect: secret('pickup_code','code',rect,['Код получения','00 00 00'],'Код получения должен остаться за кадром. Закрой всю записку.')
password=lambda rect: secret('password','password',rect,['Пароль для входа','ПРИМЕР_ПАРОЛЯ'],'Пароль даёт доступ. Не оставляй его на открытой картинке.')
L=[.04,.06,.39,.14];R=[.57,.06,.39,.14];BL=[.04,.74,.39,.14];BR=[.58,.74,.38,.14]
levels=[
 level('frame_01','Рюкзак выходит в свет','Спрячь личное. Рюкзак и идею рисунка оставь в кадре.','room',[address([.04,.08,.34,.14]),code([.64,.74,.32,.15])],keep([.26,.30,.48,.38],'Рюкзак готов к приключению',BL,['Идея рисунка','Летающий огурец'])),
 level('frame_02','Рабочее место гения','Покажи рисунок. Доступ к аккаунту оставь себе.','desk',[password(R),secret('login_code','code',BL,['Код для входа','00 00 00'],'Код для входа не должен оказаться на публичной картинке.')],keep([.22,.26,.56,.42],'Мой первый необычный проект',L,['Идея проекта','Робот без спешки'])),
 level('frame_03','Чайник под прикрытием','У чайника важный вид. Личные записки показывать не нужно.','poster',[address(L),code(BR),secret('private_meeting','private_location',BL,['Личная встреча','У моего дома','В 16:00'],'Это личная договорённость у дома героя. Ей не место в открытом посте.')],keep([.25,.26,.50,.40],'Чайный клуб готов к открытию',R,['План рисунка','Чайник на колёсах'])) ,
 level('frame_04','Плакат с характером','Плакат увидят все. Спрячь сведения для доступа.','poster',[password(L),code(R),address(BL)],keep([.25,.26,.50,.40],'Совершенно серьёзный чайник',BR,['Идея плаката','Очень важный чайник']),success='Облако прикрыло. Чайник одобряет.'),
 level('frame_05','Последний кадр — твой','Подготовь новый кадр самостоятельно. Сохрани рисунок и идеи.','desk',[code(L),address(R),password(BR)],keep([.22,.26,.56,.42],'Секреты остались за кадром',BL,['План на завтра','Дорисовать крылья']),mode='transfer',success='Готово. Кадр можно показать.')
]
content=dict(schemaVersion=1,board=dict(width=360,height=480),stickerPadding=.012,defaultStickerSize=dict(w=.30,h=.20),stickers=[dict(id='sock',label='Серьёзный носок',shortLabel='Носок',src='./assets/stickers/sock.svg',color='#e4ff69'),dict(id='cloud',label='Деловое облако',shortLabel='Облако',src='./assets/stickers/cloud.svg',color='#c9bdff'),dict(id='cucumber',label='Огурец в полёте',shortLabel='Огурец',src='./assets/stickers/cucumber.svg',color='#ffc4b5')],levels=levels)
(ROOT/'game/data/content.json').write_text(json.dumps(content,ensure_ascii=False,indent=2)+'\n', encoding='utf-8')
